package com.diberlog.jarvis.mobile;

import android.app.AlertDialog;
import android.content.Intent;
import android.net.Uri;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.*;
import org.xmlpull.v1.*;

/** User-selected documents only. No automatic file access or transmission. */
final class ChatDocuments {
    final MainActivity a;String pendingTitle="",pendingText="",pendingFormat="";
    ChatDocuments(MainActivity a){this.a=a;}
    void edit(String initial){
        LinearLayout form=a.column();form.setPadding(a.dp(16),0,a.dp(16),a.dp(16));EditText title=a.field(form,"Название","Документ JARVIS",false);title.setSingleLine(true);EditText body=a.field(form,"Текст документа",initial,false);body.setMinLines(8);body.setMaxLines(14);body.setGravity(android.view.Gravity.TOP);body.setTextSize(16);
        TextView hint=a.label("Редактируйте текст здесь. DOCX открывается как текст; исходный файл сохраняется.",13);form.addView(hint);
        ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Документ в чате").setView(scroll).setNegativeButton("Закрыть",null).create();
        form.addView(a.button("Открыть TXT / DOCX",()->{dialog.dismiss();choose();}));Button saveWord=a.button("Сохранить копию Word (.docx)",()->export(title.getText().toString(),body.getText().toString(),"docx"));saveWord.setBackground(a.surface(MainActivity.TEAL,18,false));saveWord.setTextColor(MainActivity.BG);form.addView(saveWord);
        form.addView(a.button("Сохранить копию текста (.txt)",()->export(title.getText().toString(),body.getText().toString(),"txt")));
        form.addView(a.button("Сохранить в заметки",()->{try{String text=body.getText().toString(),name=title.getText().toString().trim();if(name.isEmpty()||name.length()>500||text.isEmpty()||text.length()>200000)throw new Exception("Добавьте название и текст");JSONObject center=MobileStore.center(a);center.getJSONArray("notes").put(new JSONObject().put("id",MobileStore.id()).put("title",name).put("type","text").put("format","markdown").put("text",text).put("updatedAt",MobileStore.now()));MobileStore.save(a,center);Toast.makeText(a,"Сохранено в заметки",Toast.LENGTH_SHORT).show();}catch(Exception e){a.error(e.getMessage());}}));
        form.addView(a.button("Вставить в запрос модели",()->{String text=body.getText().toString();if(text.length()>200000){a.error("Документ слишком большой для одного запроса. Выберите фрагмент до 200 000 символов.");return;}dialog.dismiss();if(a.input!=null){a.input.setText("Отредактируй документ по моим указаниям:\n\n"+text);a.input.requestFocus();}}));dialog.show();dialog.getWindow().setBackgroundDrawable(a.shape(MainActivity.PANEL,22,false));
    }
    void choose(){a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","text/markdown","application/vnd.openxmlformats-officedocument.wordprocessingml.document"}),10);}
    void export(String title,String text,String format){if(text.isEmpty()||text.length()>1000000){a.error("Добавьте текст до 1 000 000 символов");return;}pendingTitle=title;pendingText=text;pendingFormat=format;String file=title.replaceAll("[\\\\/:*?\"<>|]","_");if(file.isBlank())file="JARVIS-document";a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(format.equals("docx")?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,file.substring(0,Math.min(80,file.length()))+"."+format),9);}
    void result(int request,int result,Intent data){if(result!=android.app.Activity.RESULT_OK||data==null||data.getData()==null){pendingText="";return;}Uri uri=data.getData();if(request==10){final String[] text={""};a.job(()->{String type=a.getContentResolver().getType(uri);try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Файл не открылся");text[0]="application/vnd.openxmlformats-officedocument.wordprocessingml.document".equals(type)?readDocx(in):PublicData.read(in,800000);}if(text[0].length()>1000000)throw new IOException("Документ больше 1 000 000 символов");},()->edit(text[0]));}else{String text=pendingText,format=pendingFormat;pendingText="";a.job(()->{try(OutputStream out=a.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Файл не открылся");if(format.equals("docx"))writeDocx(out,text);else out.write(text.getBytes(StandardCharsets.UTF_8));}},()->Toast.makeText(a,"Документ сохранён",Toast.LENGTH_SHORT).show());}}
    static String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","");}
    static void entry(ZipOutputStream zip,String name,String text)throws Exception{zip.putNextEntry(new ZipEntry(name));zip.write(text.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
    static void writeDocx(OutputStream output,String text)throws Exception{try(ZipOutputStream zip=new ZipOutputStream(output)){entry(zip,"[Content_Types].xml","<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");entry(zip,"_rels/.rels","<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");StringBuilder doc=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>");for(String line:text.split("\n",-1))doc.append("<w:p><w:r><w:t xml:space=\"preserve\">").append(xml(line)).append("</w:t></w:r></w:p>");doc.append("<w:sectPr/></w:body></w:document>");entry(zip,"word/document.xml",doc.toString());}}
    static byte[] bounded(InputStream input,int maximum)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(out.size()+n>maximum)throw new IOException("Документ слишком большой");out.write(buffer,0,n);}return out.toByteArray();}
    static String readDocx(InputStream input)throws Exception{byte[] compressed=bounded(input,8*1024*1024);try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(compressed))){ZipEntry e;int count=0;int bytes=0;while((e=zip.getNextEntry())!=null){if(++count>500)throw new IOException("Слишком много частей документа");byte[] entry=bounded(zip,e.getName().equals("word/document.xml")?8*1024*1024:2000000);bytes+=entry.length;if(bytes>16*1024*1024)throw new IOException("Распакованный документ слишком большой");if(!e.getName().equals("word/document.xml"))continue;String raw=new String(entry,StandardCharsets.UTF_8);if(raw.contains("<!DOCTYPE")||raw.contains("<!ENTITY"))throw new IOException("Внешние сущности документа запрещены");XmlPullParserFactory factory=XmlPullParserFactory.newInstance();factory.setNamespaceAware(true);XmlPullParser parser=factory.newPullParser();parser.setInput(new StringReader(raw));StringBuilder text=new StringBuilder();boolean inside=false;for(int event=parser.getEventType();event!=XmlPullParser.END_DOCUMENT;event=parser.next()){if(event==XmlPullParser.START_TAG&&parser.getName().equals("t"))inside=true;else if(event==XmlPullParser.TEXT&&inside)text.append(parser.getText());else if(event==XmlPullParser.END_TAG){if(parser.getName().equals("t"))inside=false;else if(parser.getName().equals("p"))text.append('\n');}if(text.length()>1000000)throw new IOException("Документ слишком большой");}return text.toString();}}throw new IOException("Это не документ DOCX");}
}
